99	    this.curRoundEmbedTotalTokens = 0;
100	    this.curRoundEmbedTotalTime = 0;
101	    let totalNumTokens = 0;
102	    const embedStart = performance.now();
103	    let tokenizedInputs: Array<Array<number>> = [];
104	    const tempInputs: Array<number> = [];
