137	      const curInputSize = tokenizedInputs[i].length;
138	      totalNumTokens += curInputSize;
139	      if (curInputSize > this.contextWindowSize) {
140	        throw new EmbeddingExceedContextWindowSizeError(
141	          this.contextWindowSize,
142	          curInputSize,
143	        );
144	      }
145	    }
146	    if (tokenizedInputs.length === 0) {
147	      throw new Error("InternalError: batch size is zero.");
148	    }
