162	        const curInputSize = curBatch[i].length;
163	        if (curInputSize > maxInputSize) {
164	          maxInputSize = curInputSize;
165	        }
166	      }
167	      // 3.3 Create inputs and attention mask
168	      // Padded with zeros and flattened, of size curBatchSize * maxInputSize
169	      const curBatchPaddedFlatten: Array<number> = [];
170	      // 1 for non-pad, 0 otherwise, also of size curBatchSize * maxInputSize
171	      const curAttnMask: Array<number> = [];
172	      const flattenedInputSize = curBatchSize * maxInputSize;
173	      for (let i = 0; i < curBatchSize; i++) {
174	        const padding = Array(maxInputSize - curBatch[i].length).fill(0);
175	        const ones = Array(curBatch[i].length).fill(1);
176	        curBatchPaddedFlatten.push(...curBatch[i]);
177	        curAttnMask.push(...ones);
178	        curBatchPaddedFlatten.push(...padding);
179	        curAttnMask.push(...padding);
180	      }
181	      if (
182	        curBatchPaddedFlatten.length !== flattenedInputSize ||
183	        curAttnMask.length !== flattenedInputSize
184	      ) {
185	        throw new Error(
186	          `InternalError: Expect input array to be ${flattenedInputSize}, ` +
187	            `but got ${curBatchPaddedFlatten.length}`,
188	        );
189	      }
190	      // 3.4 Convert inputs and attention mask to tvm ndarray on GPU, of shape (curBatchSize, maxInputSize)
191	      let inputNDArray = this.tvm.empty(
192	        [flattenedInputSize],
193	        "int32",
194	        this.device,
195	      );
196	      inputNDArray.copyFrom(curBatchPaddedFlatten);
197	      inputNDArray = inputNDArray.view([curBatchSize, maxInputSize]);
198	      let maskNDArray = this.tvm.empty(
199	        [flattenedInputSize],
200	        "int32",
201	        this.device,
202	      );
203	      maskNDArray.copyFrom(curAttnMask);
204	      maskNDArray = maskNDArray.view([curBatchSize, maxInputSize]);
205	
206	      // 3.5 Actual forwarding on GPU, logits of shape (curBatchSize, maxInputSize, hidden_size)
207	      const logitsCurBatchOnGPU: tvmjs.Tensor = this.prefill(
208	        inputNDArray,
209	        maskNDArray,
210	        this.params,
211	      );
212	      await this.device.sync();
213	
214	      // 3.6 Copy logits to CPU, flatten to curBatchSize * maxInputSize * hidden_size
215	      const hidden_size = logitsCurBatchOnGPU.shape[2];
216	      let logitsCurBatchOnCPU: tvmjs.Tensor = this.tvm.empty(
217	        logitsCurBatchOnGPU.shape,
218	        logitsCurBatchOnGPU.dtype,
219	        this.tvm.cpu(),
220	      );
221	      logitsCurBatchOnCPU.copyFrom(logitsCurBatchOnGPU);
222	      logitsCurBatchOnCPU = logitsCurBatchOnCPU.view([
223	        curBatchSize * maxInputSize * hidden_size,
224	      ]);
