40	export interface CreateEmbeddingResponse {
41	  /**
42	   * The list of embeddings generated by the model.
43	   */
44	  data: Array<Embedding>;
45	
46	  /**
47	   * The name of the model used to generate the embedding.
48	   */
49	  model: string;
50	
51	  /**
52	   * The object type, which is always "list".
53	   */
54	  object: "list";
55	
56	  /**
57	   * The usage information for the request.
58	   */
59	  usage: CreateEmbeddingResponse.Usage;
60	}
61	
62	/* eslint-disable-next-line @typescript-eslint/no-namespace */
63	export namespace CreateEmbeddingResponse {
64	  /**
65	   * The usage information for the request.
66	   */
67	  export interface Usage {
68	    /**
69	     * The number of tokens used by the prompt.
70	     */
71	    prompt_tokens: number;
72	
